# sqa_flashcard_echo
import re

_STOP = frozenset(("the", "a", "an", "of", "and", "or", "in", "on", "for", "to", "with", "by", "from", "as", "at", "is", "are", "was", "were", "be", "been", "it", "its", "his", "her", "their", "this", "that", "these", "those", "what", "which", "who"))
_WORD = re.compile(r"[a-z][a-z\-']+")


def applies(view):
    q = view.get("question", "")
    return len([w for w in _WORD.findall(q.lower()) if w not in _STOP]) >= 4


def before_call(view, state):
    q = view.get("question", "")
    ctx = view.get("context", "")
    qwords = set(w for w in _WORD.findall(q.lower()) if w not in _STOP)
    if not qwords:
        return None
    facts = []
    candidates = []
    for doc in ctx.split("[DOC]"):
        if not doc.strip():
            continue
        low = doc.lower()
        hits = sum(1 for w in qwords if w in low)
        if hits < max(3, int(0.5 * len(qwords))):
            continue
        if "[TLE]" in doc:
            title = " ".join(doc.split("[TLE]", 1)[1].split("[PAR]")[0].split())[:40]
        else:
            title = " ".join(doc.split())[:40]
        facts.append(("Snippet '%s' echoes the question wording (%d/%d content words)." % (title, hits, len(qwords)))[:200])
        for frag in doc.split("|")[1:]:
            frag = " ".join(frag.split())[:120]
            if frag and frag.lower() not in q.lower() and frag not in candidates:
                candidates.append(frag)
    if not facts:
        return None
    return {"facts": facts[:5], "candidates": candidates[:6]}
